const features={editorMode:'rich',selection:null,range:null,settings:null,cards:[],cardIndex:0,images:[],reports:[],comments:[],workflows:[],multiRuns:[]};
navs.splice(navs.findIndex(n=>n[0]==='ai'),0,['reports','chart','复盘与评审'],['comments','file','评论研究'],['workflows','skill','本机工作流']);
statusName.failed='运行失败';statusName.interrupted='已中断';statusName.cancelled='已取消';
const originalAPI=api;
api=async function(path,opts={}){try{return await originalAPI(path,opts)}catch(e){if(e.status===423){showUnlock();}throw e}};
function showUnlock(){if($('#unlock-form'))return;const d=$('#modal');d.innerHTML='<div class="modal-head"><h2>解锁本机工作台</h2></div><form id="unlock-form" class="modal-body">'+field('password','本机解锁密码','','password')+'<div id="unlock-error" class="modal-error"></div><button type="submit" class="primary">解锁</button></form>';if(!d.open)d.showModal();d.oncancel=e=>e.preventDefault();$('#unlock-form').onsubmit=async e=>{e.preventDefault();try{await originalAPI('local/unlock',{method:'POST',body:{password:new FormData(e.currentTarget).get('password')}});d.oncancel=null;d.close();await refreshAccounts();await render()}catch(err){$('#unlock-error').textContent=err.message}}}
function extraList(kind){return api('extras/'+kind+scope())}
function safeLink(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null}catch{return null}}
function richInline(source,images={}){const pattern=/!\[([^\]]*)\]\(media:([a-f\d-]{36})\)|\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|\*\*([^*]+)\*\*|\*([^*]+)\*/gi;let out='',at=0;for(const m of source.matchAll(pattern)){out+=esc(source.slice(at,m.index));if(m[2]){const uri=images[m[2]];out+=uri&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(uri)?'<img data-media-id="'+m[2]+'" src="'+uri+'" alt="'+esc(m[1])+'" loading="lazy">':'<span class="missing-image">[图片缺失：'+esc(m[1])+']</span>'}else if(m[4]){const url=safeLink(m[4]);out+=url?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(m[3])+'</a>':esc(m[0])}else if(m[5])out+='<strong>'+esc(m[5])+'</strong>';else out+='<em>'+esc(m[6])+'</em>';at=m.index+m[0].length}return out+esc(source.slice(at))}
function renderMarkdown(source,images={}){let out='',listType=null,code=false;for(const line of String(source||'').split('\n')){if(/^```/.test(line)){if(listType){out+='</'+listType+'>';listType=null}out+=code?'</code></pre>':'<pre><code>';code=!code;continue}if(code){out+=esc(line)+'\n';continue}const item=line.match(/^\s*(?:([-*]) |(\d+)\. )(.*)/);if(item){const type=item[1]?'ul':'ol';if(listType!==type){if(listType)out+='</'+listType+'>';out+='<'+type+'>';listType=type}out+='<li>'+richInline(item[3],images)+'</li>';continue}if(listType){out+='</'+listType+'>';listType=null}const h=line.match(/^(#{1,6})\s+(.*)/);if(h)out+='<h'+h[1].length+'>'+richInline(h[2],images)+'</h'+h[1].length+'>';else if(/^> /.test(line))out+='<blockquote>'+richInline(line.slice(2),images)+'</blockquote>';else if(/^---+$/.test(line))out+='<hr>';else if(line.trim())out+='<p>'+richInline(line,images)+'</p>';else out+=''}if(listType)out+='</'+listType+'>';if(code)out+='</code></pre>';return out}
mdHTML=source=>renderMarkdown(source,features.renderImages||state.studio?.data.image_snapshots||{});
function richToMarkdown(root){function textNode(n){if(n.nodeType===3)return n.nodeValue||'';if(n.nodeType!==1)return '';const tag=n.tagName.toLowerCase(),inside=Array.from(n.childNodes).map(textNode).join('');if(tag==='img'){const id=n.getAttribute('data-media-id');return id&&/^[a-f\d-]{36}$/i.test(id)?'!['+(n.getAttribute('alt')||'图片').replace(/[\[\]]/g,'')+'](media:'+id+')':''}if(['script','style','iframe','object','svg'].includes(tag))return '';if(tag==='strong'||tag==='b')return '**'+inside+'**';if(tag==='em'||tag==='i')return '*'+inside+'*';if(tag==='a'){const href=safeLink(n.getAttribute('href'));return href?'['+inside.replace(/\]/g,'')+']('+href+')':inside}if(/^h[1-6]$/.test(tag))return '\n\n'+'#'.repeat(Number(tag[1]))+' '+inside.trim()+'\n\n';if(tag==='blockquote')return '\n\n> '+inside.trim().replace(/\n/g,'\n> ')+'\n\n';if(tag==='li')return '- '+inside.trim()+'\n';if(tag==='br')return '\n';if(tag==='pre')return '\n\n```\n'+n.textContent+'\n```\n\n';if(tag==='hr')return '\n\n---\n\n';if(['p','div','ul','ol'].includes(tag))return '\n'+inside+'\n';return inside}return Array.from(root.childNodes).map(textNode).join('').replace(/\n{3,}/g,'\n\n').trim()}
function editorChanged(){if(!state.studio)return;const rich=$('#rich-editor');if(features.editorMode==='rich'&&rich){state.studio.data.body=richToMarkdown(rich);$('#editor-body').value=state.studio.data.body}if($('#word-count'))$('#word-count').textContent=state.studio.data.body.replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/\s/g,'').length+' 字';sessionStorage.setItem('ms-recovery-'+state.studio.id,JSON.stringify(state.studio.data));markDirty()}
function captureSelection(){const source=$('#editor-body');if(features.editorMode==='source'&&source&&source.selectionEnd>source.selectionStart){features.selection={start:source.selectionStart,end:source.selectionEnd,text:source.value.slice(source.selectionStart,source.selectionEnd)};return}const rich=$('#rich-editor'),selection=window.getSelection();if(!rich||!selection?.rangeCount||!rich.contains(selection.anchorNode)||!rich.contains(selection.focusNode))return;const r=selection.getRangeAt(0);features.range=r.cloneRange();const selected=selection.toString();if(!selected.trim())return;const body=state.studio.data.body,start=body.indexOf(selected);if(start<0||body.indexOf(selected,start+1)!==-1){features.selection=null;return}features.selection={start,end:start+selected.length,text:selected}}
const baseStudioPage=pages.studio;
pages.studio=async()=>{const html=await baseStudioPage();if(!state.studio)return html;features.selection=null;features.range=null;const commands=[['bold','粗体'],['italic','斜体'],['heading','标题'],['quote','引用'],['list','列表'],['link','链接']];return html.replace('Markdown 编辑器','正文编辑器').replace('<textarea class="editor-body"',`<div class="rich-toolbar"><div class="inline">${btn('可视化','editor-rich','','small '+(features.editorMode==='rich'?'primary':''))}${btn('Markdown','editor-source','','small '+(features.editorMode==='source'?'primary':''))}${commands.map(([a,l])=>btn(l,'rich-'+a,'','small')).join('')}${btn('插入图片','insert-image','','small')}${btn('导入文稿','import-document','','small')}</div></div><div id="rich-editor" contenteditable="true" role="textbox" aria-label="富文本正文" aria-multiline="true" class="rich-editor" ${features.editorMode==='source'?'hidden':''}>${renderMarkdown(state.studio.data.body,state.studio.data.image_snapshots)}</div><textarea class="editor-body" ${features.editorMode==='rich'?'hidden':''}`).replace('<div class="ai-actions">',`<div class="inline selection-actions">${btn('改写所选段落','ai-selection','','small')}${btn('审阅稿件','ai-review','','small')}${btn('多模型候选','multi-model','','small')}${btn('运行与费用','open-usage','','small')}</div><div class="ai-actions">`)+`<div class="notice" style="margin-top:12px">${(state.studio.data.validation_warnings||[]).map(esc).join('；')||'当前稿件符合已配置的平台基础规则。'} 选区改写保留原稿，只有采纳才替换选区。</div>`};
const baseBindPage=bindPage;
bindPage=function(){baseBindPage();if($('#rich-editor')){const rich=$('#rich-editor');rich.oninput=editorChanged;rich.onmouseup=captureSelection;rich.onkeyup=captureSelection;rich.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));editorChanged()};$('#editor-body').onselect=captureSelection;$('#editor-body').onmouseup=captureSelection;}if($('#run-filter'))$('#run-filter').onchange=e=>{features.runFilter=e.target.value;render()};};
act['editor-rich']=()=>{features.editorMode='rich';$('#rich-editor').innerHTML=renderMarkdown(state.studio.data.body,state.studio.data.image_snapshots);$('#rich-editor').hidden=false;$('#editor-body').hidden=true};act['editor-source']=()=>{features.editorMode='source';$('#editor-body').value=state.studio.data.body;$('#editor-body').hidden=false;$('#rich-editor').hidden=true};
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-act^="rich-"]'))e.preventDefault()});
for(const cmd of ['bold','italic','heading','quote','list'])act['rich-'+cmd]=()=>{if(features.editorMode!=='rich'){toast('请切换到可视化模式使用格式工具');return}const rich=$('#rich-editor');rich.focus();if(features.range){const s=window.getSelection();s.removeAllRanges();s.addRange(features.range)}if(cmd==='heading')document.execCommand('formatBlock',false,'h2');else if(cmd==='quote')document.execCommand('formatBlock',false,'blockquote');else if(cmd==='list')document.execCommand('insertUnorderedList');else document.execCommand(cmd);editorChanged();captureSelection()};
act['rich-link']=()=>{const range=features.range?.cloneRange();modal('插入链接',field('url','公开链接 URL','','url'),async f=>{const url=safeLink(f.url);if(!url)throw new Error('链接必须是 http/https');$('#rich-editor').focus();if(range){const s=window.getSelection();s.removeAllRanges();s.addRange(range)}document.execCommand('createLink',false,url);editorChanged()})};
async function resizeImage(file){if(file.size>20*1024*1024)throw Error('原图最大 20 MB');const bitmap=await createImageBitmap(file),scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let blob;for(const quality of [.9,.75,.6,.45]){blob=await new Promise(r=>canvas.toBlob(r,'image/webp',quality));if(blob.size<=2*1024*1024)break}if(!blob||blob.size>2*1024*1024)throw Error('图片压缩后仍超过 2 MB，请缩小尺寸');return {data_uri:'data:image/webp;base64,'+bytesBase64(new Uint8Array(await blob.arrayBuffer())),width:canvas.width,height:canvas.height}}
async function uploadImage(file,{insert=false}={}){const img=await resizeImage(file);const asset=await api('records/asset'+scope(),{method:'POST',body:{data:{title:file.name||'图片',...img,asset_type:'image',license:'待补充：请确认有权使用此图片'}}});if(insert&&state.studio){state.studio.data.image_snapshots||={};state.studio.data.image_snapshots[asset.id]=img.data_uri;const marker='!['+fileName(file.name||'图片')+'](media:'+asset.id+')';if(features.editorMode==='rich'){$('#rich-editor').focus();if(features.range){const s=window.getSelection();s.removeAllRanges();s.addRange(features.range)}document.execCommand('insertHTML',false,'<p>'+richInline(marker,{[asset.id]:img.data_uri})+'</p>');editorChanged()}else{const area=$('#editor-body'),at=area.selectionStart;area.value=area.value.slice(0,at)+'\n\n'+marker+'\n\n'+area.value.slice(area.selectionEnd);state.studio.data.body=area.value;editorChanged()}await flush()}return asset}
act['insert-image']=()=>pickFile('image/png,image/jpeg,image/webp',async file=>{await uploadImage(file,{insert:true});toast('图片已存入当前账号素材库，并插入稿件')});
act.assets=async()=>{features.images=await records('asset');modal('当前账号素材与图片',`<div class="notice">${esc(acc().name)} 的独立素材。图片会嵌入稿件修订快照和 JSON/自动备份，不依赖外部图床。</div><div class="inline">${btn('添加文本资料','add-asset','type="button"','primary small')}${btn('上传图片','upload-asset-image','type="button"','small')}${btn('图像模型生成','generate-image','type="button"','small')}${btn('导入文档/Markdown','import-document','type="button"','small')}</div><div class="asset-grid">${features.images.map(a=>`<article class="asset-tile">${a.data.data_uri?`<img src="${a.data.data_uri}" alt="${esc(a.data.title)}" loading="lazy">`:ico('file')}<b>${esc(a.data.title)}</b><small>${esc(a.data.license||'许可未填写')}</small><div class="inline">${btn('编辑','asset-detail',`data-id="${a.id}" type="button"`,'small')}${btn('移入回收状态','delete-asset',`data-id="${a.id}" type="button"`,'ghost small')}</div></article>`).join('')||empty('暂无素材','上传你自己的图片或保存有出处的文本资料。')}</div>`,null,true)};
act['upload-asset-image']=()=>pickFile('image/png,image/jpeg,image/webp',async file=>{await uploadImage(file);await act.assets();toast('图片已保存，可编辑版权说明')});
act['asset-detail']=e=>{const a=features.images.find(x=>x.id===dataId(e));modal('编辑素材',`${a.data.data_uri?`<img src="${a.data.data_uri}" class="asset-detail-img" alt="图片预览">`:''}${field('title','素材名称',a.data.title)}${a.data.data_uri?'':field('body','资料正文',a.data.body||'','textarea')}${field('url','来源链接',a.data.url||'','url')}${field('license','许可 / 引用范围',a.data.license||'')}`,async f=>{await api('records/asset/'+a.id+scope(),{method:'PATCH',body:{revision:a.revision,data:f}});toast('素材已更新；旧稿件仍使用原图片快照')},true)};
act['delete-asset']=async e=>{await api('records/asset/'+dataId(e)+scope(),{method:'DELETE'});await act.assets();toast('已标记删除，历史稿件中的图片快照仍保留')};
const baseRunCard=runCard;
runCard=function(r){const html=baseRunCard(r),d=r.data;return html+(r.status==='running'?`<div class="candidate live-candidate">${esc(d.partial_output||'正在等待首个文本片段…')}</div>`:'')+(['failed','interrupted','cancelled'].includes(r.status)&&(d.partial_output||d.output)?`<div class="candidate">${esc(d.partial_output||d.output)}</div>${btn('接续这次生成','resume-run',`data-id="${r.id}"`,'small')}${d.draft?btn('仅采纳已完成初稿','accept-partial-draft',`data-id="${r.id}"`,'small'):''}`:'')};
async function executeAI(action,extra={}){await flush();const c=state.studio;if(!c)throw Error('请先打开稿件');const aid=state.accountId,feedback=$('#ai-feedback'),instruction=$('#ai-instruction')?.value||'';if(feedback)feedback.textContent='真实调用中，分段输出会逐步保存…';const poll=setInterval(async()=>{if(state.accountId!==aid||state.studio?.id!==c.id)return;try{state.runs=await studioRuns(c);if($('#candidates'))$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===c.id).slice(0,5).map(runCard).join('')}catch{}},800);document.querySelectorAll('.ai-actions button').forEach(b=>b.disabled=true);try{const r=await api('runs?accountId='+aid,{method:'POST',body:{content_id:c.id,source_revision:c.revision,action,instruction,parameters:$('#run-temperature')?.value!==''&&$('#run-temperature')?.value!==undefined?{temperature:Number($('#run-temperature').value)}:{},max_tokens:Number($('#run-max-tokens')?.value)||undefined,allow_fallback:!!$('#allow-fallback')?.checked,...extra}});toast(r.status==='cancelled'?'已取消，部分结果保留':'结果已保存为独立候选');if(r.data?.report_id)features.lastReport=r.data.report_id;return r;}catch(e){toast(e.message)}finally{clearInterval(poll);if(state.accountId===aid&&state.studio?.id===c.id){state.runs=await studioRuns(c);if($('#candidates'))$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===c.id).slice(0,5).map(runCard).join('');if(feedback)feedback.textContent='运行已结束。原稿保持可恢复。'}document.querySelectorAll('.ai-actions button').forEach(b=>b.disabled=false)}}
runAI=executeAI;act['ai-selection']=()=>{captureSelection();if(!features.selection)return toast('请先选中唯一的一段文字；重复段落可切到 Markdown 模式选择准确范围');return executeAI('rewrite_selection',{selection:features.selection})};act['ai-review']=()=>executeAI('review');act['resume-run']=e=>executeAI('resume',{resumed_from:dataId(e)});
act['accept-partial-draft']=async e=>{const r=state.runs.find(r=>r.id===dataId(e));modal('采纳后处理前已完成的初稿',`<div class="notice warning">后处理未完成。这里只采纳已完整生成的初稿，保留当前正文修订。</div><div class="candidate">${esc(r.data.draft)}</div>`,async()=>{await flush();state.studio=await api('runs/'+r.id+'/accept'+scope(),{method:'POST',body:{candidate:'draft',expected_revision:state.studio.revision}});state.openId=state.studio.id;await render()})};
act['derive-content']=async()=>{await flush();const c=state.contents.find(c=>c.id===state.layoutId),p=c.data.platform==='wechat'?'xhs':'wechat';modal('改编为'+platform(p),`<div class="notice">来源：《${esc(c.data.title)}》v${c.revision}。新建独立稿件，AI 将重新组织开头、结构和篇幅，结果先保存为候选。</div>${select('provider_id','本次模型',c.data.provider_id||acc().data.default_provider_id||'',[['','使用账号/全局路由'],...state.providers.filter(p=>p.data.enabled&&p.data.protocol!=='image').map(p=>[p.id,p.data.title])])}${field('instruction','改编要求','','textarea')}`,async f=>{const r=await api('records/content'+scope(),{method:'POST',body:{data:{title:c.data.title+' · '+platform(p)+'版',body:'',summary:'来源：'+c.data.title,source_content_id:c.id,platform:p,topic_id:c.data.topic_id,writing_skill_version_id:null,humanize_enabled:false,humanize_skill_version_id:null,provider_id:f.provider_id||null}}});state.studio=r;await go('studio',r.id);await executeAI('adapt',{instruction:f.instruction})})};
act['compare-run']=async e=>{await flush();const r=state.runs.find(r=>r.id===dataId(e));if(['titles','review','report','research','comment_reply'].includes(r.data.action)){modal('独立建议 · 不替换正文','<div class="report-markdown">'+renderMarkdown(r.data.output)+'</div>',null,true);return}state.compareRun=r;const original=r.data.selection?.text||state.studio.data.body;modal('差异比较与人工采纳',`<div class="notice">候选基于 v${r.source_revision}，当前 v${state.studio.revision}。${r.data.selection?'采纳只替换原选区，其余正文保留。':'采纳会创建新修订。'}</div><div class="diff-view">${diffLines(original,r.data.output)}</div><details><summary>完整候选</summary><div class="candidate">${esc(r.data.output)}</div></details>${r.data.humanize_skill_version_id?`<details><summary>去 AI 味之前的初稿</summary><div class="candidate">${esc(r.data.draft||'')}</div>${btn('仅采纳初稿','accept-draft','type="button"','small')}</details>`:''}`,async()=>acceptRun('output'),true)};
editProvider=async function(p){const status=p?await api('providers/'+p.id+'/status'):null;modal(p?'编辑模型与调用能力':'添加模型与调用能力',`<div class="notice">密钥只在本机服务端保存。自定义公网域名会进行 DNS 解析与 IP 固定校验；本机接口必须显式授权。价格由你按供应商实际口径填写。</div><div class="field-grid">${field('title','配置名称',p?.data.title||'')}${select('protocol','接口协议',p?.data.protocol||'openai',[['openai','OpenAI Chat Completions 兼容'],['responses','OpenAI Responses 原生'],['anthropic','Anthropic Messages'],['gemini','Google Gemini 原生'],['image','图像生成 / Images API']])}${field('base_url','API Base URL',p?.data.base_url||'https://api.openai.com/v1','url','例如 https://api.openai.com/v1 或本机 http://127.0.0.1:11434/v1',true)}${field('model','模型 ID',p?.data.model||'')}${field('api_key',status?.mask?'API Key（'+status.mask+'；留空保留）':'API Key（本机接口可留空）','','password')}${select('currency','价格 / 预算币种',p?.data.currency||'CNY',[['CNY','人民币 CNY'],['USD','美元 USD']])}${field('image_price','图像：每张估算价格',p?.data.image_price??0,'number')}${select('image_api_flavor','图像接口参数',p?.data.image_api_flavor||'gpt',[['gpt','GPT Image：WebP / quality'],['compatible','兼容图像：b64_json']])}${field('max_tokens','默认输出 Token',p?.data.max_tokens||8000,'number','不设软件最低门槛或固定上限；单次任务可覆盖默认值。数值须符合供应商能力，费用预算仍生效。')}${field('input_price','输入价格 / 百万 Token',p?.data.input_price??'','number')}${field('output_price','输出价格 / 百万 Token',p?.data.output_price??'','number')}${field('per_run_limit','单次创作预算',p?.data.per_run_limit??1,'number')}${field('daily_limit','账号每日创作预算',p?.data.daily_limit??10,'number')}${field('monthly_limit','账号每月创作预算',p?.data.monthly_limit??100,'number')}${field('timeout_ms','超时毫秒（10,000–300,000）',p?.data.timeout_ms||120000,'number')}${select('token_parameter','兼容协议输出参数',p?.data.token_parameter||'max_tokens',[['max_tokens','max_tokens'],['max_completion_tokens','max_completion_tokens']])}${select('enabled','是否启用',p?.data.enabled===false?'false':'true',[['true','启用'],['false','停用']])}</div><label class="radio-card"><input name="stream_enabled" type="checkbox" ${p?.data.stream_enabled!==false?'checked':''}>服务商支持流式输出</label><label class="radio-card"><input name="supports_temperature" type="checkbox" ${p?.data.supports_temperature?'checked':''}>模型支持 temperature 参数</label><label class="radio-card"><input name="allow_custom" type="checkbox" ${p?.data.allow_custom?'checked':''}>显式允许此自定义公网域名（仍拒绝内网与重定向）</label><label class="radio-card"><input name="allow_loopback" type="checkbox" ${p?.data.allow_loopback?'checked':''}>显式允许此本机模型接口（仅 localhost / 127.0.0.1 / ::1）</label>`,async f=>{for(const k of ['stream_enabled','supports_temperature','allow_custom','allow_loopback'])f[k]=f[k]==='on';f.enabled=f.enabled==='true';await api('records/provider'+(p?'/'+p.id:'')+(state.accountId?scope():''),{method:p?'PATCH':'POST',body:{data:f,revision:p?.revision}});await render();toast('模型配置已保存，调用能力以真实测试为准')},true)};
const tasks=[['titles','标题建议'],['comment_reply','评论建议'],['rewrite_selection','选区改写'],['resume','接续生成'],['draft','正文创作'],['outline','大纲'],['research','选题研究'],['rewrite','改写'],['adapt','跨平台改编'],['humanize','后处理'],['review','审稿'],['report','数据复盘']];
const baseAIPage=pages.ai;
pages.ai=async()=>{const [html,defaults,auth]=await Promise.all([baseAIPage(),api('preferences/ai'),api('local/auth-status')]);features.aiDefaults=defaults;return (!auth.credential_available?'<div class="notice warning">系统凭证库'+(auth.credential_state==='pending'?'正在连接':'暂不可用')+'，连接成功前无法保存 API Key。可以继续本机写作；稍后在应用菜单点击「重新连接系统凭证库」。</div>':'')+html+`<section class="panel"><div class="panel-head"><h2>全局与账号任务路由</h2>${btn('运行记录 / 费用','open-usage','','small')}</div><div class="inline">${btn('配置全局默认与路由','global-models','','primary small')}${acc()?btn('配置当前账号路由','account-models','','small'):''}</div><p class="field-hint">优先级：本次显式选择 → 任务配置 → 账号任务路由 → 账号默认 → 全局任务路由 → 全局默认。备用模型只在明确启用、且在允许名单内时使用。</p></section>`};
function routeForm(config,ps){const options=[['','使用上一级配置'],...ps.filter(p=>p.data.enabled&&p.data.protocol!=='image').map(p=>[p.id,p.data.title+' / '+p.data.model])];return `<div class="field-grid">${select('default_provider_id','默认模型',config.default_provider_id||'',options)}${select('fallback_provider_id','允许的备用模型',config.fallback_provider_id||'',options)}${tasks.map(([k,l])=>select('task_'+k,l+'模型',config.task_models?.[k]||'',options)).join('')}</div><label class="radio-card"><input type="checkbox" name="allow_fallback" ${config.allow_fallback?'checked':''}>允许失败后使用上面明确选择的备用模型（创作时仍需选择允许备用）</label>`}
function routeData(f){return {default_provider_id:f.default_provider_id||null,fallback_provider_id:f.fallback_provider_id||null,allowed_fallback_ids:f.fallback_provider_id?[f.fallback_provider_id]:[],allow_fallback:f.allow_fallback==='on',task_models:Object.fromEntries(tasks.map(([k])=>[k,f['task_'+k]||null]))}}
act['global-models']=()=>modal('全局模型路由',routeForm(features.aiDefaults||{},state.providers),async f=>{await api('preferences/ai',{method:'PUT',body:{data:routeData(f)}});await render();toast('全局模型路由已保存')},true);
act['account-models']=()=>modal(acc().name+' · 任务模型路由',routeForm(acc().data,state.providers),async f=>{await api('accounts/'+acc().id,{method:'PATCH',body:{name:acc().name,status:acc().status,data:routeData(f)}});await refreshAccounts();await render();toast('账号路由已保存')},true);
const baseEditAccount=editAccount;
editAccount=async function(a){await baseEditAccount(a);const skills=await api('records/skill'+(a?'?accountId='+a.id:(state.accountId?scope():'')));const grid=$('#modal-form .field-grid'),box=document.createElement('div');box.className='field wide';box.innerHTML=select('preferred_humanize','常用去 AI 味 Skill（仅推荐）',a?.data.preferred_humanize||'',[['','不设置'],...skills.filter(s=>s.data.skill_type==='humanize'&&(!s.data.scope_account_id||s.data.scope_account_id===a?.id)).map(s=>[s.data.version_id,s.data.title])],'新任务的后处理开关仍默认关闭');grid.append(box);const original=$('#modal-form').onsubmit;$('#modal-form').onsubmit=async e=>{const pref=$('#f-preferred_humanize').value;await original(e);if(!$('#modal').open){const target=a||state.accounts[state.accounts.length-1];if(target)await api('accounts/'+target.id,{method:'PATCH',body:{name:target.name,status:target.status,data:{preferred_humanize:pref||null}}});await refreshAccounts();}}};
async function previewSkillImport(d,source,preview){
 preview=preview||await api('skills/preview'+(state.accountId?scope():''),{method:'POST',body:{...d,source}});
 modal('预览并导入 Skill',`<div class="notice">来源 ${esc(source)}<br><strong>${esc(preview.title)}</strong> · v${esc(preview.version)}${d.github_source?'<br>固定提交 '+esc(d.github_source.commit):''}<br>文字规则用于模型输入，脚本附件仅保存，不自动执行、调用外部服务或支付。</div><div class="field-grid">${select('skill_type','用途',preview.suggested_type,[['writing','写作'],['humanize','去 AI 味'],['editing','编辑'],['review','审阅'],['research','对标研究'],['breakdown','文章拆解'],['planning','创作规划'],['post_review','发布后复盘']])}${select('platform','适用平台','all',[['all','通用'],['wechat','公众号'],['xhs','小红书']])}${select('scope_account_id','可用范围','',[['','所有自己的账号可选'],...state.accounts.map(a=>[a.id,'仅 '+a.name])])}</div>${preview.warnings.length?'<details open><summary>导入兼容处理</summary><ul>'+preview.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></details>':''}<details open><summary>参考文档（${preview.reference_files.length}）</summary><div class="candidate">${esc(preview.reference_files.join('\n')||'未附带参考文档')}</div></details><details open><summary>只读脚本附件（${preview.attachment_files?.length||0}）</summary><div class="candidate">${esc(preview.attachment_files?.join('\n')||'无')}</div></details><details><summary>查看原始 SKILL.md</summary><div class="candidate">${esc(preview.source_markdown)}</div></details>`,async f=>{await api('records/skill'+(state.accountId?scope():''),{method:'POST',body:{data:{...d,...f,enabled:true,source}}});await render();toast('Skill 已导入，规则、参考文档、只读附件和版本已保存');},true);
}
act['import-skill']=()=>pickFile('.md,.zip',async file=>{if(file.size>1048576)throw Error('Skill 文件最大 1 MB');const d=file.name.toLowerCase().endsWith('.zip')?{zip_base64:bytesBase64(new Uint8Array(await file.arrayBuffer()))}:{markdown:await file.text()};try{await previewSkillImport(d,file.name)}catch(err){modal('Skill 文件未通过检查','<div class="notice warning">'+esc(err.message)+'</div>',null,true)}});
const skillSourcePage=pages.skills;pages.skills=async()=>'<div class="inline" style="justify-content:flex-end;margin-bottom:12px">'+btn('从 GitHub 地址安装','import-github-skill','','small')+'</div>'+await skillSourcePage();
act['import-github-skill']=()=>{modal('从 GitHub 地址安装 Skill',`<div class="notice">粘贴公开仓库中的 Skill 目录或 SKILL.md 链接。会下载该目录的完整包，固定到同一次提交，再进入与上传安装相同的预览。</div>${field('url','GitHub 地址','','url','例如 https://github.com/redfox-data/redfox-community/tree/main/skills/wechat-write')}<details><summary>分支识别（可选）</summary>${field('ref','指定分支或标签','','text','分支名含 / 且链接有歧义时填写完整名称')}</details>`,async f=>{const gen=$('#modal').dataset.generation,aid=state.accountId,r=await api('skills/github-preview'+(aid?scope():''),{method:'POST',body:{url:f.url,ref:f.ref}});if(!$('#modal').open||$('#modal').dataset.generation!==gen||state.accountId!==aid)return;await previewSkillImport(r.package,r.package.source,r);},true);$('#modal-form [type=submit]').textContent='读取并预览';};
const baseSkillDetail=act['skill-detail'];act['skill-detail']=async e=>{await baseSkillDetail(e);const s=state.skillDetail;const row=document.createElement('div');row.className='inline';row.style.marginTop='15px';row.innerHTML=btn('调整账号可用范围','skill-scope','type="button"','small')+btn('恢复历史规则为新版本','skill-rollback','type="button"','small');$('#modal-form .modal-body').prepend(row);if(s.data.github_source||Object.keys(s.data.attachments||{}).length){const provenance=document.createElement('details');provenance.innerHTML='<summary>安装来源与只读附件</summary><p>'+esc(s.data.github_source?.url||s.data.source||'上传文件')+'</p>'+(s.data.github_source?'<p>提交 '+esc(s.data.github_source.commit)+'</p>':'')+'<div class="candidate">'+esc(Object.keys(s.data.attachments||{}).join('\n')||'没有脚本附件')+'</div><p class="field-hint">附件只读保存，不执行，也不作为模型参考文本。</p>';row.after(provenance)}if(s.data.import_info?.warnings?.length){const info=document.createElement('details');info.innerHTML='<summary>导入兼容处理与原始文件</summary><ul>'+s.data.import_info.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul><div class="candidate">'+esc(s.data.source_markdown||s.data.markdown)+'</div>';row.after(info)}};
act['skill-scope']=()=>{const s=state.skillDetail;modal('Skill 可用范围',select('scope_account_id','账号范围',s.data.scope_account_id||'',[['','所有自己的账号可选'],...state.accounts.map(a=>[a.id,'仅 '+a.name])]),async f=>{await api('records/skill/'+s.id+(state.accountId?scope():''),{method:'PATCH',body:{revision:s.revision,data:{scope_account_id:f.scope_account_id||null}}});await render()})};
act['skill-rollback']=async()=>{const s=state.skillDetail,revs=await api('records/skill/'+s.id+'/revisions'+(state.accountId?scope():''));modal('以新版本恢复历史规则',`${select('revision','历史版本',revs[revs.length-1].revision,revs.map(r=>[r.revision,'v'+r.data.version+' / '+fmt(r.created_at)]))}${field('version','新版本号',s.data.version+'-restored.'+(s.revision+1))}<div class="notice">恢复创建新快照，不覆盖过去用过的规则版本。</div>`,async f=>{await api('skills/'+s.id+'/rollback'+(state.accountId?scope():''),{method:'POST',body:{revision:Number(f.revision),version:f.version,expected_revision:s.revision}});await render();toast('历史规则已保存为新版本')})};
const baseSettingsPage=pages.settings;
pages.settings=async()=>{const [html,rules,backups,auth]=await Promise.all([baseSettingsPage(),api('preferences/platform_rules'),api('local/backups'),api('local/auth-status')]);features.rules=rules;features.backups=backups;features.auth=auth;return title('为个人本机使用，补齐每一环。','所有稿件与图片留在本机。自动备份、可选解锁、平台规则和提示词由你配置。')+`<div class="cards settings-cards"><section class="card"><h3>本机自动备份</h3><p>${backups.config.enabled===false?'已关闭':'每天在应用运行时自动备份'} · 保留 ${backups.config.retention||14} 份<br>最近：${backups.config.last_backup_at?fmt(backups.config.last_backup_at):'尚未执行'}</p><div class="inline">${btn('立即备份','local-backup-now','','primary small')}${btn('查看 / 配置','backup-manager','','small')}</div></section><section class="card"><h3>本机解锁保护</h3><p>${auth.enabled?'已启用本机解锁密码':'当前使用本机系统用户，无额外密码'}。可设置自动锁定，密码不会进入备份。</p><div class="inline">${btn('设置密码','local-password','','small')}${auth.enabled?btn('立即锁定','local-lock','','small'):''}</div></section><section class="card"><h3>平台规则与提示词</h3><p>按自己确认的平台当前要求配置标题、正文、图片数量和卡片比例。</p><div class="inline">${btn('平台规则','platform-rules','','small')}${btn('提示词模板','prompt-templates','','small')}</div></section></div>`+html.replace(/<div class="page-heading">[\s\S]*?<\/div><div class="split">/,'<div class="split">')};
act['platform-rules']=()=>{const rules=features.rules;modal('平台基础规则配置',`<div class="notice">这些是你可编辑的工作台校验参数，不代表平台实时官方限制。草稿超限会提示，导出前再次检查。</div><div class="field-grid">${['wechat','xhs'].map(p=>`<div class="wide"><h3>${platform(p)}</h3></div>${field(p+'_title','标题字数上限',rules[p].title_limit,'number')}${field(p+'_body','正文字数上限',rules[p].body_limit,'number')}${field(p+'_images','图片数量上限',rules[p].max_images,'number')}${select(p+'_ratio','图文卡片比例',rules[p].card_ratio,[['3:4','3:4 竖版'],['4:3','4:3 横版']])}`).join('')}</div>`,async f=>{const d={...rules};for(const p of ['wechat','xhs'])d[p]={title_limit:Number(f[p+'_title']),body_limit:Number(f[p+'_body']),max_images:Number(f[p+'_images']),card_ratio:f[p+'_ratio']};await api('preferences/platform_rules',{method:'PUT',body:{data:d}});await render();toast('规则已更新')},true)};
act['prompt-templates']=async()=>{const p=await api('preferences/prompts');modal('任务提示词模板',tasks.map(([k,l])=>field(k,l+'补充要求',p[k]||'','textarea')).join(''),async f=>{await api('preferences/prompts',{method:'PUT',body:{data:f}});toast('提示词已保存，后续运行会锁定输入快照')},true)};
act['local-password']=()=>modal(features.auth.enabled?'修改本机解锁密码':'设置本机解锁密码',`${features.auth.enabled?field('current_password','当前密码','','password'):''}${field('password','新密码（至少 8 个字符）','','password')}${field('confirm','再次输入新密码','','password')}${field('auto_lock_minutes','无操作自动锁定分钟（0 为不自动锁定）',features.auth.auto_lock_minutes||0,'number')}${features.auth.enabled?'<label class="radio-card"><input name="disable" type="checkbox">移除额外解锁保护（须校验当前密码）</label>':''}`,async f=>{if(!f.disable&&f.password!==f.confirm)throw Error('两次密码不一致');await api('local/password',{method:'POST',body:{...f,disable:f.disable==='on'}});await render();toast('本机保护设置已更新')});
act['local-lock']=async()=>{await api('local/lock',{method:'POST',body:{}});showUnlock()};
act['local-backup-now']=async()=>{const r=await api('local/backups',{method:'POST',body:{}});toast('本机备份完成：'+r.filename);if(state.page==='settings')await render()};
act['backup-manager']=async()=>{const b=await api('local/backups');modal('本机备份管理',`<div class="notice">${esc(b.directory)}<br>备份包含图片快照和扩展模块，不含 API Key / 解锁密码。自动备份只在应用运行时执行。</div><label class="radio-card"><input name="enabled" type="checkbox" ${b.config.enabled!==false?'checked':''}>启用每日自动备份</label>${field('retention','保留份数（2–60）',b.config.retention||14,'number')}<div class="revision-list">${b.files.map(f=>`<div class="list-row"><div class="list-main"><h4>${esc(f.filename)}</h4><p>${(f.bytes/1024).toFixed(1)} KB · SHA-256 ${f.sha256.slice(0,12)}…</p></div>${btn('导出','download-backup',`data-file="${f.filename}" type="button"`,'small')}</div>`).join('')||empty('尚无备份','可以先执行一次立即备份。')}</div>`,async f=>{await api('preferences/backup',{method:'PUT',body:{data:{...b.config,enabled:f.enabled==='on',retention:Number(f.retention)}}});await render()},true)};
act['download-backup']=async e=>{const r=await fetch('/api/local/backups/'+encodeURIComponent(e.dataset.file));if(!r.ok)throw Error('备份下载失败');download(await r.blob(),e.dataset.file)};
act['restore-backup']=()=>pickFile('.json,.gz',async file=>{const b=file.name.endsWith('.gz')?await api('local/backup-parse',{method:'POST',body:{base64:bytesBase64(new Uint8Array(await file.arrayBuffer()))}}):JSON.parse(await file.text());modal('恢复备份到空工作空间',`<div class="notice warning">${esc(file.name)}<br>${b.accounts?.length||0} 个账号、${b.records?.length||0} 条内容与素材、${b.extras?.length||0} 条复盘/工作流记录。<br>只支持空工作空间，密钥需要重新录入。</div>`,async()=>{await api('backup',{method:'POST',body:b});await refreshAccounts();await render();toast('所有模块数据已恢复')})});
const palette={lavender:['#f2edf8','#4f3f70','#9b80c7'],sage:['#eef3ee','#3f594b','#7b9c84'],ink:['#f3f0eb','#343e4e','#788293']};
function canvasLines(ctx,value,width){const lines=[];let line='';for(const ch of String(value||'')){if(ch==='\n'){lines.push(line);line='';continue}if(ctx.measureText(line+ch).width>width&&line){lines.push(line);line=ch}else line+=ch}lines.push(line);return lines}
async function paintCard(card,index,total,{preview=false}={}){await document.fonts.ready;const ratio=features.layoutConfig.ratio||'3:4',w=1080,h=ratio==='4:3'?810:1440,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d'),theme=palette[features.layoutConfig.theme||'lavender'],[bg,ink,accent]=theme;ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);ctx.fillStyle=accent;ctx.fillRect(75,65,50,6);ctx.font='22px sans-serif';ctx.fillText(acc().name.slice(0,28),75,120);ctx.fillStyle=ink;const size=Number(features.layoutConfig.font_size)||32,lineHeight=size*1.65;let y=card.type==='cover'?230:210;ctx.font=(card.type==='cover'?48:38)+'px sans-serif';const titleLines=canvasLines(ctx,card.title||'',930);if(titleLines.length>(ratio==='4:3'?3:5))throw Error('第 '+(index+1)+' 张标题过长，请在卡片编辑中缩短标题');for(const line of titleLines){ctx.fillText(line,75,y);y+=(card.type==='cover'?72:58)}y+=25;
 if(card.image_id){const uri=features.layoutContent.data.image_snapshots?.[card.image_id]||features.images.find(a=>a.id===card.image_id)?.data.data_uri;if(!uri)throw Error('第 '+(index+1)+' 张图片缺失');const image=await createImageBitmap(new Blob([Uint8Array.from(atob(uri.split(',')[1]),x=>x.charCodeAt(0))],{type:uri.slice(5,uri.indexOf(';'))}));ctx.save();ctx.font=size+'px sans-serif';const captionHeight=card.text?canvasLines(ctx,card.text,930).length*lineHeight+20:0;ctx.restore();const maxH=h-y-150-captionHeight,scale=Math.min(930/image.width,maxH/image.height);if(scale<=0){image.close();throw Error('卡片标题占用过多空间，请缩短标题')}const iw=image.width*scale,ih=image.height*scale;ctx.drawImage(image,75+(930-iw)/2,y,iw,ih);image.close();y+=ih+20;}
 if(card.text){ctx.font=size+'px sans-serif';const lines=canvasLines(ctx,card.text,930);if(y+lines.length*lineHeight>h-105){if(!preview)throw Error('第 '+(index+1)+' 张文字超出画面，请分页或减少文字');ctx.fillStyle='#bd6b6b';ctx.font='22px sans-serif';ctx.fillText('文字超出画面，请编辑后再导出',75,h-55)}else{ctx.fillStyle=ink;for(const line of lines){ctx.fillText(line,75,y);y+=lineHeight}}}
 ctx.fillStyle=accent;ctx.font='20px sans-serif';ctx.fillText(String(index+1).padStart(2,'0')+' / '+String(total).padStart(2,'0'),75,h-55);ctx.fillText('MEDIA STUDIO',820,h-55);return canvas;
}
function autoCards(c,ratio='3:4',fontSize=32){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');ctx.font=fontSize+'px sans-serif';const h=ratio==='4:3'?810:1440,capacity=Math.max(1,Math.floor((h-370)/(fontSize*1.65))),plain=String(c.data.body||'').replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/^#+\s*/gm,'').replace(/\*\*/g,'');const lines=canvasLines(ctx,plain,930),cards=[{id:crypto.randomUUID(),type:'cover',title:c.data.title,text:c.data.summary||'',image_id:null}];for(let i=0;i<lines.length;i+=capacity)cards.push({id:crypto.randomUUID(),type:'text',title:'',text:lines.slice(i,i+capacity).join('\n'),image_id:null});return cards}
async function cardPreview(){const panel=$('#card-preview');if(!panel)return;panel.innerHTML='';const card=features.cards[features.cardIndex];if(!card)return;try{const canvas=await paintCard(card,features.cardIndex,features.cards.length,{preview:true});canvas.style.width='100%';canvas.style.height='auto';panel.append(canvas)}catch(e){panel.innerHTML='<div class="notice warning">'+esc(e.message)+'</div>'}}
async function saveCardLayout(){if(features.cardSaving){await features.cardSaving;if(!features.cardDirty)return}if(!features.cardDirty||!features.layoutContent)return;const c=features.layoutContent,data={...c.data,layout_json:{...features.layoutConfig,cards:structuredClone(features.cards)},card_image_ids:[...new Set(features.cards.map(x=>x.image_id).filter(Boolean))]};features.cardDirty=false;features.cardSaving=api('records/content/'+c.id+'?accountId='+c.account_id,{method:'PATCH',body:{revision:c.revision,data}}).then(saved=>{features.layoutContent=saved;const index=state.contents.findIndex(x=>x.id===saved.id);if(index>=0)state.contents[index]=saved;if(state.studio?.id===saved.id)state.studio=saved;if($('#layout-save-state'))$('#layout-save-state').textContent='排版已保存 · v'+saved.revision}).catch(e=>{features.cardDirty=true;if($('#layout-save-state'))$('#layout-save-state').textContent='排版未保存：'+e.message;throw e}).finally(()=>features.cardSaving=null);await features.cardSaving;if(features.cardDirty)await saveCardLayout()}
const originalFlush=flush;flush=async function(){await originalFlush();clearTimeout(features.layoutTimer);if(features.cardDirty)await saveCardLayout()};
function changeLayout(){features.cardDirty=true;clearTimeout(features.layoutTimer);features.layoutTimer=setTimeout(()=>saveCardLayout().catch(e=>toast(e.message)),1200);cardPreview();if($('#layout-save-state'))$('#layout-save-state').textContent='排版待保存…'}
pages.layout=async()=>{const [contents,assets,rules,providers]=await Promise.all([records('content'),records('asset'),api('preferences/platform_rules'),records('provider')]);state.contents=contents;state.providers=providers;features.images=assets.filter(a=>a.data.asset_type==='image');const c=contents.find(c=>c.id===state.openId||c.id===state.layoutId)||contents[0];state.openId=null;if(!c)return title('让图片与文字，一起讲故事。','先创建一篇稿件，再选择排版与导出。')+empty('暂无稿件','可以从选题池开始。','add-content','新建内容');state.layoutId=c.id;features.layoutContent=c;features.rules=rules;features.layoutConfig={theme:'lavender',font_size:32,ratio:rules[c.data.platform].card_ratio,...c.data.layout_json};features.cards=c.data.layout_json?.cards?.length?structuredClone(c.data.layout_json.cards):autoCards(c,features.layoutConfig.ratio,features.layoutConfig.font_size);features.cardIndex=Math.min(features.cardIndex,features.cards.length-1);features.cardDirty=!c.data.layout_json?.cards?.length;return title('让图片与文字，一起讲故事。',acc().name+' · 原图、文字卡片、封面和顺序都可独立编辑')+`<section class="panel"><div class="field-grid">${select('layout-content','当前稿件',c.id,contents.map(c=>[c.id,c.data.title]))}${select('layout-theme','排版风格',features.layoutConfig.theme,[['lavender','浅紫'],['sage','草木'],['ink','墨色']])}${select('layout-ratio','卡片比例',features.layoutConfig.ratio,[['3:4','3:4 / 1080×1440'],['4:3','4:3 / 1080×810']])}${field('card-font','正文字号',features.layoutConfig.font_size,'number')}</div><div class="inline">${btn('重新按正文分页','repaginate','','small')}${btn('添加文字卡','add-text-card','','small')}${btn('添加图片卡','add-image-card','','small')}${btn('保存排版','save-layout','','primary small')}${btn('回编辑器','layout-edit','','small')}${btn('跨平台 AI 改编','derive-content','','small')}</div><div id="layout-save-state" class="field-hint">当前稿件 v${c.revision} · 当前 ${features.cards.length} 张 / 配置上限 ${rules[c.data.platform].max_images} 张</div>${(c.data.validation_warnings||[]).length?'<div class="notice warning">'+c.data.validation_warnings.map(esc).join('；')+'</div>':''}</section><div class="designer-grid"><section class="panel"><div class="panel-head"><h2>图文顺序</h2>${tag(features.cards.length+' 张')}</div><div class="card-thumbnails">${features.cards.map((card,i)=>btn('<b>'+String(i+1).padStart(2,'0')+'</b><span>'+esc(card.title||card.text?.slice(0,18)||'图片卡')+'</span>','select-card',`data-index="${i}"`,'card-thumb '+(i===features.cardIndex?'selected':''))).join('')}</div><div id="card-form"></div><div class="inline" style="margin-top:16px">${btn('向前移','card-up','','small')}${btn('向后移','card-down','','small')}${btn('删除此卡','card-delete','','danger small')}</div><div class="notice" style="margin-top:20px">卡片超出画面的文字会阻止导出，请调整分页。图片采用完整缩放，不裁掉原图。图片许可请在素材库填写。</div></section><section class="panel"><div class="panel-head"><h2>实际导出预览</h2>${tag('Canvas PNG','gray')}</div><div id="card-preview" class="card-preview"></div></section></div><section class="panel"><div class="panel-head"><h2>导出与人工发布</h2><span class="caption">导出前会保存当前排版版本</span></div><div class="inline">${btn('Markdown 与图片 ZIP','export-complete-md','','small')}${btn('公众号 HTML + 原图素材','export-complete-html','','small')}${btn('小红书 PNG + 正文 ZIP','export-cards','','primary small')}${btn('安排人工发布','schedule-current','','small')}</div><details style="margin-top:20px"><summary>公众号手机阅读预览</summary><div class="phone" style="margin-top:20px"><div class="phone-top">${platform(c.data.platform)}</div><article class="phone-content"><h1>${esc(c.data.title)}</h1>${renderMarkdown(c.data.body,c.data.image_snapshots)}</article></div></details></section>`};
function fillCardForm(){const node=$('#card-form'),c=features.cards[features.cardIndex];if(!node||!c)return;node.innerHTML=field('card-title','这一张的标题',c.title||'')+field('card-text','这一张的正文',c.text||'','textarea')+select('card-image','图片（可选）',c.image_id||'',[['','无图片'],...features.images.map(a=>[a.id,a.data.title])]);$('#f-card-title').oninput=e=>{c.title=e.target.value;changeLayout()};$('#f-card-text').oninput=e=>{c.text=e.target.value;changeLayout()};$('#f-card-image').onchange=e=>{c.image_id=e.target.value||null;changeLayout()};cardPreview()}
const previousBind=bindPage;bindPage=function(){previousBind();if($('#card-form')){fillCardForm();$('#f-layout-theme').onchange=e=>{features.layoutConfig.theme=e.target.value;changeLayout()};$('#f-layout-ratio').onchange=e=>{features.layoutConfig.ratio=e.target.value;changeLayout()};$('#f-card-font').onchange=e=>{features.layoutConfig.font_size=Math.min(48,Math.max(20,Number(e.target.value)||32));e.target.value=features.layoutConfig.font_size;changeLayout()}}};
act['save-layout']=async()=>{features.cardDirty=true;await saveCardLayout();toast('排版和图片顺序已保存')};
act['select-card']=e=>{features.cardIndex=Number(e.dataset.index);document.querySelectorAll('.card-thumb').forEach((n,i)=>n.classList.toggle('selected',i===features.cardIndex));fillCardForm()};
async function refreshLayoutDesigner(){features.cardDirty=true;await saveCardLayout();await render()}
act.repaginate=()=>{modal('重新按正文生成分页','<div class="notice warning">会用当前正文重新生成封面和分页，原排版保留在历史修订中。</div>',async()=>{features.cards=autoCards(features.layoutContent,features.layoutConfig.ratio,features.layoutConfig.font_size);features.cardIndex=0;await refreshLayoutDesigner()})};
act['add-text-card']=async()=>{features.cards.push({id:crypto.randomUUID(),type:'text',title:'',text:'',image_id:null});features.cardIndex=features.cards.length-1;await refreshLayoutDesigner()};
act['add-image-card']=()=>{if(!features.images.length)return toast('请先在素材库上传一张图片');modal('添加图片卡',select('image','当前账号图片',features.images[0].id,features.images.map(a=>[a.id,a.data.title])),async f=>{features.cards.push({id:crypto.randomUUID(),type:'image',title:'',text:'',image_id:f.image});features.cardIndex=features.cards.length-1;await refreshLayoutDesigner()})};
act['card-up']=async()=>{const i=features.cardIndex;if(i<1)return;[features.cards[i-1],features.cards[i]]=[features.cards[i],features.cards[i-1]];features.cardIndex--;await refreshLayoutDesigner()};
act['card-down']=async()=>{const i=features.cardIndex;if(i>=features.cards.length-1)return;[features.cards[i+1],features.cards[i]]=[features.cards[i],features.cards[i+1]];features.cardIndex++;await refreshLayoutDesigner()};
act['card-delete']=async()=>{if(features.cards.length===1)return toast('至少保留一张卡片');features.cards.splice(features.cardIndex,1);features.cardIndex=Math.min(features.cardIndex,features.cards.length-1);await refreshLayoutDesigner()};
act['export-cards']=async()=>{await flush();const c=features.layoutContent,rule=features.rules.xhs,limit=rule.max_images;if([...c.data.title].length>rule.title_limit||[...c.data.body.replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/\s/g,'')].length>rule.body_limit)throw Error('标题或正文超过你配置的小红书限制，请先跨平台改编或调整平台规则');if(features.cards.length>limit)throw Error('当前 '+features.cards.length+' 张，超过你配置的 '+limit+' 张，请拆分内容或调整规则');const files=[];for(let i=0;i<features.cards.length;i++){const canvas=await paintCard(features.cards[i],i,features.cards.length);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));files.push({name:String(i+1).padStart(2,'0')+'.png',data:new Uint8Array(await blob.arrayBuffer())})}files.push({name:'正文.md',data:new TextEncoder().encode('# '+c.data.title+'\n\n'+c.data.body.replace(/!\[[^\]]*\]\(media:[^)]+\)/g,'')+'\n\n'+(c.data.tags||''))},{name:'发布核对.txt',data:new TextEncoder().encode('目标账号：'+acc().name+'\n稿件修订：v'+c.revision+'\n按文件编号顺序发布。请核对账号、事实、版权和当前平台规则。')});download(zipStore(files),fileName(c.data.title)+'-图文素材.zip');toast('已按保存顺序导出 '+features.cards.length+' 张 PNG 与正文')};
function imageExportFiles(c){return Object.entries(c.data.image_snapshots||{}).map(([id,uri])=>{const match=uri.match(/^data:(image\/\w+);base64,(.*)$/),ext=match[1].split('/')[1];return {id,name:'images/'+id+'.'+(ext==='jpeg'?'jpg':ext),data:Uint8Array.from(atob(match[2]),x=>x.charCodeAt(0))}})}
act['export-complete-md']=async()=>{await flush();const c=features.layoutContent,images=imageExportFiles(c);let body=c.data.body;for(const image of images)body=body.replaceAll('media:'+image.id,image.name);download(zipStore([...images,{name:'正文.md',data:new TextEncoder().encode('# '+c.data.title+'\n\n'+body)}]),fileName(c.data.title)+'-Markdown素材.zip');toast('已导出正文和当前稿件图片快照')};
act['export-complete-html']=async()=>{await flush();const c=features.layoutContent,files=imageExportFiles(c),article=document.createElement('article');article.innerHTML='<h1>'+esc(c.data.title)+'</h1>'+renderMarkdown(c.data.body,c.data.image_snapshots);const color=palette[features.layoutConfig.theme][2];for(const n of article.querySelectorAll('p'))n.setAttribute('style','margin:0 0 20px;font-size:16px;line-height:1.9;letter-spacing:.4px');for(const n of article.querySelectorAll('h1,h2,h3'))n.setAttribute('style','font-size:'+({H1:25,H2:21,H3:18}[n.tagName])+'px;line-height:1.6;margin:24px 0 18px;color:'+color);for(const n of article.querySelectorAll('img')){n.setAttribute('style','display:block;max-width:100%;height:auto;margin:18px auto');n.removeAttribute('loading')};for(const n of article.querySelectorAll('blockquote'))n.setAttribute('style','border-left:3px solid '+color+';padding-left:14px;color:#888');article.setAttribute('style','max-width:640px;margin:auto;padding:24px;color:#333;font-family:system-ui');const html='<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><title>'+esc(c.data.title)+'</title><body>'+article.outerHTML+'</body></html>';files.push({name:'公众号正文.html',data:new TextEncoder().encode(html)},{name:'导出说明.txt',data:new TextEncoder().encode('HTML 使用内联样式与内嵌图片，可离线打开。公众号后台可能清洗 data URI，请将 images 文件夹中的原图在后台重新上传，再核对段落与图片。')});download(zipStore(files),fileName(c.data.title)+'-公众号素材.zip');toast('已导出内联样式 HTML 与原图文件')};
async function chooseTable(file,callback){const ext=file.name.split('.').pop().toLowerCase();if(ext==='csv'){const raw=(await file.text()).replace(/^\uFEFF/,'');return callback(parseCSV(raw),{filename:file.name,source_format:'csv',raw:raw.slice(0,2*1024*1024)})}if(ext==='xlsx'){const parsed=await api('office-preview'+scope(),{method:'POST',body:{filename:file.name,base64:bytesBase64(new Uint8Array(await file.arrayBuffer()))}});if(parsed.sheets.length===1)return callback(parsed.sheets[0].rows,{filename:file.name,source_format:'xlsx',sheet:parsed.sheets[0].name});return modal('选择 Excel 工作表',select('sheet','工作表','0',parsed.sheets.map((s,i)=>[i,s.name+' / '+s.rows.length+' 行'])),async f=>callback(parsed.sheets[Number(f.sheet)].rows,{filename:file.name,source_format:'xlsx',sheet:parsed.sheets[Number(f.sheet)].name}))}throw Error('请选择 CSV 或 XLSX；旧版 XLS 请先另存为 XLSX')}
function dateForImport(value,excelMode){if(value===''||value===null||value===undefined)throw Error('采集时间不能为空');if(excelMode&&Number.isFinite(Number(value))){const date=new Date(Date.UTC(1899,11,30)+Number(value)*86400000);if(!Number.isFinite(date.valueOf()))throw Error('Excel 日期无效');return date.toISOString()}const date=new Date(value);if(!Number.isFinite(date.valueOf()))throw Error('采集时间无效，请使用带时区的日期或选择 Excel 日期序号');return date.toISOString()}
act['import-metrics']=()=>pickFile('.csv,.xlsx',file=>chooseTable(file,async(table,meta)=>{const headers=table[0]||[],rows=table.slice(1),jobs=(await records('job')).filter(j=>j.data.status==='published');if(!jobs.length)throw Error('请先确认至少一篇真实发布的作品');const fields=[['job_id','作品 ID 或标题'],['observed_at','采集时间'],['reads','阅读'],['likes','点赞'],['saves','收藏'],['comments','评论'],['shares','分享'],['note','口径说明']];const aliases={job_id:['job_id','作品id','作品ID','标题','作品'],observed_at:['observed_at','采集时间','统计时间','日期'],reads:['reads','阅读','阅读量'],likes:['likes','点赞','点赞数'],saves:['saves','收藏','收藏数'],comments:['comments','评论','评论数'],shares:['shares','分享','分享数'],note:['note','说明','口径']};const options=[['','不导入 / 未知'],...headers.map((h,i)=>[String(i),h||'第 '+(i+1)+' 列'])];modal('指标字段映射',`<div class="notice">目标账号：${esc(acc().name)}<br>${esc(meta.filename)} · ${rows.length} 行。指标按作品最新累计快照统计；缺失字段留空。</div><div class="mapping-grid">${fields.map(([k,l])=>{const n=headers.findIndex(h=>aliases[k].includes(String(h).trim()));return select(k,l,n<0?'':String(n),k==='job_id'?[['__fixed__','所有行归属下面选定作品'],...options]:options)}).join('')}${select('fixed_job','固定作品',jobs[0].id,jobs.map(j=>[j.id,j.data.title]))}${select('date_mode','日期格式','text',[['text','日期字符串 / ISO 时间'],['excel','Excel 日期序号（按 UTC 解释）']])}</div><div class="candidate">${esc(JSON.stringify(table.slice(0,4),null,2))}</div>`,async f=>{if(rows.length>500)throw Error('请每批导入最多 500 行');const mapped=rows.map((row,i)=>{const data={};for(const [k]of fields)data[k]=f[k]===''?'':f[k]==='__fixed__'?f.fixed_job:row[Number(f[k])]??'';const matches=jobs.filter(j=>j.id===data.job_id||j.data.title===data.job_id);if(matches.length!==1)throw Error('第 '+(i+2)+' 行作品无法唯一匹配，请映射作品 ID 或使用固定作品');data.job_id=matches[0].id;data.observed_at=dateForImport(data.observed_at,f.date_mode==='excel');for(const k of ['reads','likes','saves','comments','shares'])if(data[k]!==''&&(!Number.isFinite(Number(data[k]))||Number(data[k])<0))throw Error('第 '+(i+2)+' 行 '+k+' 无效');return data});modal('确认指标导入预览',`<div class="notice">${esc(acc().name)} · ${mapped.length} 行。相同批次再次导入会被拒绝。</div><div class="candidate">${esc(JSON.stringify(mapped.slice(0,8),null,2))}</div>`,async()=>{const r=await api('metrics-import'+scope(),{method:'POST',body:{rows:mapped,meta:{...meta,mapping:f}}});await render();toast('已导入 '+r.count+' 行，映射与批次可追溯')},true)},true)}));
const baseTopicsPage=pages.topics;
pages.topics=async()=>{const html=await baseTopicsPage();return html.replace('<div class="toolbar">','<div class="inline" style="margin-bottom:15px">'+btn('批量导入 CSV / XLSX','import-topics','','small')+btn('导出当前账号选题','export-topics','','small')+btn('AI 研究建议','research-ideas','','small')+'</div><div class="toolbar">')};
act['import-topics']=()=>pickFile('.csv,.xlsx',file=>chooseTable(file,async(table,meta)=>{const headers=table[0]||[],rows=table.slice(1),fields=[['title','选题标题'],['description','描述'],['angle','创作角度'],['tags','关键词'],['status','状态'],['priority','优先级']],options=[['','不导入'],...headers.map((h,i)=>[String(i),h||'第 '+(i+1)+' 列'])];modal('选题导入映射',`<div class="notice">归属 ${esc(acc().name)} · ${esc(meta.filename)} · ${rows.length} 行</div><div class="mapping-grid">${fields.map(([k,l])=>{const i=headers.findIndex(h=>String(h).trim()===k||String(h).trim()===l);return select(k,l,i<0?'':String(i),options)}).join('')}</div><label class="radio-card"><input name="skip_duplicates" type="checkbox" checked>跳过当前账号或本批次的同名选题</label>`,async f=>{if(f.title==='')throw Error('请指定标题列');const mapped=rows.map(row=>Object.fromEntries(fields.map(([k])=>[k,f[k]===''?'':row[Number(f[k])]||''])));modal('确认选题导入',`<div class="candidate">${esc(JSON.stringify(mapped.slice(0,8),null,2))}</div>`,async()=>{const r=await api('imports/topics'+scope(),{method:'POST',body:{rows:mapped,skip_duplicates:f.skip_duplicates==='on',meta:{...meta,mapping:f}}});await render();toast('新增 '+r.count+' 个选题，跳过 '+r.skipped+' 个同名项')},true)},true)}));
act['export-topics']=async()=>{const rows=await records('topic'),fields=['title','description','angle','tags','status','priority'],quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"';download('\uFEFF'+fields.join(',')+'\n'+rows.map(r=>fields.map(k=>quote(r.data[k])).join(',')).join('\n'),fileName(acc().name)+'-选题.csv','text/csv;charset=utf-8')};
const baseEditTopic=editTopic;editTopic=function(t,status){baseEditTopic(t,status);const input=$('#f-title'),result=document.createElement('div');result.className='field-hint';input.after(result);let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(input.value.length<3){result.textContent='';return}try{const found=await api('similar-topics'+scope(),{method:'POST',body:{title:input.value}});result.textContent=found.filter(x=>x.id!==t?.id).slice(0,3).map(x=>'相似 '+Math.round(x.similarity*100)+'%：'+x.data.title).join('；')}catch{}},500)})};
act['import-document']=()=>{if(!acc())return toast('请先选择账号');pickFile('.md,.txt,.docx',async file=>{const parsed=file.name.toLowerCase().endsWith('.docx')?await api('office-preview'+scope(),{method:'POST',body:{filename:file.name,base64:bytesBase64(new Uint8Array(await file.arrayBuffer()))}}):{title:file.name.replace(/\.(md|txt)$/i,''),body:await file.text(),warnings:[]};modal('文稿导入预览',`${field('title','标题',parsed.title)}${select('destination','导入为','content',[['content','当前账号稿件'],['asset','当前账号资料素材']])}${field('license','来源 / 许可说明','用户从本机文件导入')}${field('body','正文（可编辑）',parsed.body,'textarea')}${parsed.warnings?.length?'<div class="notice warning">'+parsed.warnings.map(esc).join('；')+'</div>':''}`,async f=>{const kind=f.destination,r=await api('records/'+kind+scope(),{method:'POST',body:{data:kind==='content'?{title:f.title,body:f.body,summary:'',platform:acc().platform,writing_skill_version_id:null,humanize_enabled:false,source_file:file.name}:{title:f.title,body:f.body,license:f.license,source_file:file.name}}});if(kind==='content')await go('studio',r.id);else await render();toast('本机文件已导入，原文件未被修改')},true)})};
act['import-markdown-folder']=()=>{const input=document.createElement('input');input.type='file';input.webkitdirectory=true;input.multiple=true;input.style.display='none';document.body.append(input);input.addEventListener('cancel',()=>input.remove(),{once:true});input.onchange=async()=>{try{const files=[...input.files].filter(f=>f.name.endsWith('.md')&&!f.webkitRelativePath.split('/').some(x=>x.startsWith('.')));if(files.length>100)throw Error('每批最多导入 100 个 Markdown 文件');modal('只读导入 Markdown / Obsidian 文件夹',`<div class="notice">当前账号 ${esc(acc().name)} · ${files.length} 个 Markdown 文件。只读取文字，不改写原目录，不自动导入外部图片或执行插件。</div><div class="candidate">${esc(files.map(f=>f.webkitRelativePath).join('\n'))}</div>`,async()=>{for(const file of files){if(file.size>200000)throw Error(file.name+' 超过 200 KB');await api('records/asset'+scope(),{method:'POST',body:{data:{title:file.name.replace(/\.md$/,''),body:await file.text(),source_file:file.webkitRelativePath,license:'本机只读导入，版权待确认'}}})}await render();toast('已完成只读 Markdown 导入')},true)}catch(e){toast(e.message)}finally{input.remove()}};input.click()};
const baseLibraryPage=pages.library;
pages.library=async()=>{const html=await baseLibraryPage();return '<div class="inline" style="justify-content:flex-end;margin-bottom:12px">'+btn('导入文稿','import-document','','small')+btn('只读导入 Markdown 文件夹','import-markdown-folder','','small')+'</div>'+html};
const baseAnalytics=pages.analytics;
pages.analytics=async()=>{const html=await baseAnalytics();return html+`<section class="panel"><div class="panel-head"><h2>数据驱动复盘</h2></div><p class="subtitle">仅使用当前账号已发布作品的最新真实指标，输出带证据 ID 的假设和下一步实验，不编造未知数据。</p><div class="inline" style="margin-top:15px">${btn('生成 AI 复盘','generate-report','','primary small')}${btn('查看历史复盘','nav-reports','','small')}${btn('导入批次记录','import-history','','small')}</div></section>`};
act['import-history']=async()=>{const rows=await api('imports/history'+scope());modal('指标 / 选题导入记录',rows.length?rows.map(r=>`<div class="list-row"><div class="list-main"><h4>${esc(r.data.filename||'导入批次')}</h4><p>${fmt(r.created_at)} · ${esc(r.data.source_format||'CSV')} · ${esc(r.kind||'metrics')}</p><details><summary>映射与来源摘要</summary><pre class="candidate">${esc(JSON.stringify({...r.data,raw:r.data.raw?'已保存原始文本，不在此展开':undefined},null,2))}</pre></details></div></div>`).join(''):empty('暂无导入批次','手工录入的指标在操作审计中记录。'),null,true)};
async function backgroundAnalysis(action,more={}){const providers=(await records('provider')).filter(p=>p.data.enabled);modal(action==='report'?'基于真实数据的 AI 复盘':'当前账号 AI 研究',`${select('provider_id','模型','',[['','按账号/全局路由'],...providers.map(p=>[p.id,p.data.title])])}${field('instruction','本次重点','','textarea')}<div class="notice">模型会读取当前账号允许的资料；生成独立建议，不会自动修改稿件或发布。</div>`,async f=>{toast('正在真实调用模型，结果会保留在复盘与评审模块');const r=await api('runs'+scope(),{method:'POST',body:{action,provider_id:f.provider_id||null,instruction:f.instruction,...more}});await go('reports');if(r.data?.report_id)await openReport(r.data.report_id)})}
act['generate-report']=()=>backgroundAnalysis('report');act['research-ideas']=()=>backgroundAnalysis('research');
pages.reports=async()=>{features.reports=await extraList('report');features.evaluations=await extraList('evaluation');return title('把反馈，变成下一次更好的表达。',acc().name+' · 复盘、研究建议、审阅和盲评结果独立留存。','generate-report','生成真实数据复盘')+`<div class="inline" style="margin-bottom:20px">${btn('AI 研究建议','research-ideas','','small')}${btn('多模型盲评','multi-model','','small')}${btn('调用与费用','open-usage','','small')}</div><section class="panel">${features.reports.length?features.reports.map(r=>`<div class="list-row"><span class="stat-icon">${ico('chart')}</span><div class="list-main"><h4>${esc(r.data.title)}</h4><p>${fmt(r.updated_at)} · ${esc(r.data.report_type||'报告')} · ${r.data.source_ids?.length||0} 个来源引用</p></div>${btn('查看与编辑','report-detail',`data-id="${r.id}"`,'small')}</div>`).join(''):empty('暂无报告','可以从真实指标生成复盘，或在创作页审阅稿件。','','','chart')}</section><section class="panel"><div class="panel-head"><h2>人工盲评记录</h2></div>${features.evaluations.length?features.evaluations.map(e=>`<div class="list-row"><div class="list-main"><h4>${esc(e.data.title||'多模型比较')}</h4><p>${fmt(e.created_at)} · ${e.data.run_ids?.length||0} 个候选 · 主观评分</p></div>${btn('查看','evaluation-detail',`data-id="${e.id}"`,'small')}</div>`).join(''):empty('暂无盲评','在 AI 创作页选择两个或三个模型生成候选。','','','spark',true)}</section>`};
async function openReport(rid){const r=await api('extras/report/'+rid+scope());features.currentReport=r;modal(r.data.title,`<div class="notice">引用 ID：${esc((r.data.source_ids||[]).join('、')||'暂无')}<br>AI 分析为建议，事实与因果仍需人工核查。</div><div class="report-markdown">${renderMarkdown(r.data.body)}</div><div class="inline">${btn('修改报告文字','edit-report','type="button"','small')}${btn('导出 Markdown','export-report','type="button"','small')}${r.data.report_type==='research'?btn('将一个建议纳入选题池','report-topic','type="button"','primary small'):''}</div>`,null,true)}
act['report-detail']=e=>openReport(dataId(e));act['edit-report']=()=>{const r=features.currentReport;modal('编辑报告',field('title','标题',r.data.title)+field('body','报告正文',r.data.body,'textarea'),async f=>{await api('extras/report/'+r.id+scope(),{method:'PATCH',body:{revision:r.revision,data:f}});await render();toast('报告已保存新修订')},true)};
act['export-report']=()=>download('# '+features.currentReport.data.title+'\n\n'+features.currentReport.data.body,fileName(features.currentReport.data.title)+'.md','text/markdown;charset=utf-8');
act['report-topic']=()=>{const r=features.currentReport;modal('人工确认一个研究选题',field('title','选择其中一个选题标题','')+field('angle','你的差异化角度','','textarea'),async f=>{await api('records/topic'+scope(),{method:'POST',body:{data:{...f,status:'idea',priority:'normal',report_id:r.id}}});await go('topics');toast('研究建议已由你确认进入当前账号选题池')})};
pages.comments=async()=>{features.comments=await extraList('comment');return title('认真听见，读者在说什么。',acc().name+' · 手工录入与导入评论，AI 回复仅作为建议。','add-comment','记录评论')+`<div class="notice">不会自动读取平台评论或发送回复。你可以复制已确认的建议，手动到平台回复。</div><div class="inline" style="margin-bottom:18px">${btn('导入评论 CSV','import-comments','','small')}${btn('将高频问题转成选题','comment-topic','','small')}</div><section class="panel">${features.comments.length?features.comments.map(c=>`<div class="list-row"><div class="list-main"><h4>${esc(c.data.text)}</h4><p>${esc(c.data.author||'匿名读者')} · ${esc(c.data.category||'待分类')} · ${fmt(c.created_at)}</p></div>${btn('编辑','edit-comment',`data-id="${c.id}"`,'small')}${btn('AI 分类 / 回复建议','reply-comment',`data-id="${c.id}"`,'small')}</div>`).join(''):empty('还没有评论记录','保存真实读者问题，累积下次创作的方向。','add-comment','记录评论','file')}</section>`};
function commentForm(c){modal('保存真实评论',field('author','读者称呼',c?.data.author||'')+field('text','评论内容',c?.data.text||'','textarea')+select('category','人工分类',c?.data.category||'待分类',['待分类','问题','共鸣','质疑','风险'].map(x=>[x,x])),async f=>{if(!f.text.trim())throw Error('评论不能为空');await api('extras/comment'+(c?'/'+c.id:'')+scope(),{method:c?'PATCH':'POST',body:{revision:c?.revision,data:f}});await render()})}
act['add-comment']=()=>commentForm();act['edit-comment']=e=>commentForm(features.comments.find(c=>c.id===dataId(e)));act['reply-comment']=e=>backgroundAnalysis('comment_reply',{comment_id:dataId(e)});
act['import-comments']=()=>pickFile('.csv',async file=>{const rows=parseCSV((await file.text()).replace(/^\uFEFF/,'')),header=rows.shift();const ti=header.findIndex(x=>['text','评论','评论内容'].includes(x)),ai=header.findIndex(x=>['author','作者','读者'].includes(x));if(ti<0)throw Error('需要 text 或 评论内容 表头');if(rows.length>200)throw Error('每批最多 200 条');modal('确认导入真实评论',`<div class="notice">${esc(acc().name)} · ${rows.length} 条</div><div class="candidate">${esc(rows.slice(0,5).map(r=>r[ti]).join('\n'))}</div>`,async()=>{for(const r of rows)if(r[ti]?.trim())await api('extras/comment'+scope(),{method:'POST',body:{data:{text:r[ti],author:r[ai]||'',category:'待分类',source_file:file.name}}});await render()})});
act['comment-topic']=()=>{if(!features.comments.length)return toast('请先记录真实评论');modal('从读者问题创建选题',select('comment','来源评论',features.comments[0].id,features.comments.map(c=>[c.id,c.data.text.slice(0,70)]))+field('title','你确认的选题标题','')+field('angle','差异化角度','','textarea'),async f=>{await api('records/topic'+scope(),{method:'POST',body:{data:{title:f.title,angle:f.angle,comment_id:f.comment,status:'idea',priority:'normal'}}});await go('topics')})};
pages.workflows=async()=>{features.workflows=await extraList('workflow');return title('让重复步骤，成为可控的流程。',acc().name+' · 只在本机应用运行时执行，只生成候选和报告。','add-workflow','创建工作流')+`<div class="notice">每一步使用已配置的真实模型。结果独立留存，正文采纳由你确认。排期仅在本机应用打开且解锁时生效；可暂停，失败不会跳过步骤。</div><section class="panel">${features.workflows.length?features.workflows.map(w=>`<div class="list-row"><div class="list-main"><h4>${esc(w.data.title)}</h4><p>${w.data.nodes.length} 步 · ${esc(({running:'正在执行',completed:'已完成',failed:'失败',paused:'已暂停',idle:'待运行'})[w.data.status]||w.data.status)} · ${w.data.schedule_enabled?'下一次 '+fmt(w.data.next_run_at):'手动启动'}</p>${w.data.error?'<p class="warning">'+esc(w.data.error)+'</p>':''}</div>${btn('编辑','edit-workflow',`data-id="${w.id}"`,'small')}${btn(w.data.status==='running'?'查看进度':'运行','run-workflow',`data-id="${w.id}"`,'primary small')}${btn(w.data.status==='paused'?'恢复为待运行':'暂停','pause-workflow',`data-id="${w.id}"`,'small')}${btn('结果','workflow-results',`data-id="${w.id}"`,'small')}</div>`).join(''):empty('把常用步骤串起来','例如：基于稿件列提纲 → 生成候选 → 审阅候选。','add-workflow','创建工作流','skill')}</section>`};
async function editWorkflow(w){const [providers,contents]=await Promise.all([records('provider'),records('content')]),nodes=w?.data.nodes||[{action:'outline',instruction:'',provider_id:null},{action:'draft',instruction:'参考上一步提纲，产出完整候选',provider_id:null}];const stepHTML=(n,i)=>`<div class="workflow-node"><div class="inline"><b>步骤 ${i+1}</b></div>${select('step_'+i,'任务',n?.action||'skip',[['skip','不使用此步骤'],...tasks.filter(([k])=>['research','outline','draft','rewrite','review','report','humanize','adapt'].includes(k))])}${select('model_'+i,'模型',n?.provider_id||'',[['','使用任务路由'],...providers.filter(p=>p.data.enabled&&p.data.protocol!=='image').map(p=>[p.id,p.data.title])])}${field('instruction_'+i,'步骤补充要求',n?.instruction||'','textarea')}</div>`;modal('本机内容工作流',field('title','名称',w?.data.title||'我的创作工作流')+select('content_id','稿件（纯研究 / 复盘可不选）',w?.data.content_id||'',[['','不绑定稿件'],...contents.map(c=>[c.id,c.data.title])])+`<div class="workflow-nodes">${Array.from({length:6},(_,i)=>stepHTML(nodes[i],i)).join('')}</div><label class="radio-card"><input name="schedule_enabled" type="checkbox" ${w?.data.schedule_enabled?'checked':''}>开启本机排期（会产生模型费用）</label>`+select('schedule','频率',w?.data.schedule||'weekly',[['weekly','每周'],['daily','每天']])+field('next_run_at','下次运行时间',localInput(new Date(w?.data.next_run_at||Date.now()+86400000)),'datetime-local'),async f=>{const prepared=Array.from({length:6},(_,i)=>({action:f['step_'+i],provider_id:f['model_'+i]||null,instruction:f['instruction_'+i]})).filter(n=>n.action!=='skip');if(!prepared.length)throw Error('至少选择一个步骤');if(!f.content_id&&prepared.some(n=>!['report','research'].includes(n.action)))throw Error('该流程包含正文任务，请指定稿件');const data={...w?.data,title:f.title,nodes:prepared,content_id:f.content_id||null,schedule_enabled:f.schedule_enabled==='on',schedule:f.schedule,next_run_at:f.next_run_at?new Date(f.next_run_at).toISOString():null,status:'idle'};await api('extras/workflow'+(w?'/'+w.id:'')+scope(),{method:w?'PATCH':'POST',body:{revision:w?.revision,data}});await render()},true)}
act['add-workflow']=()=>editWorkflow();act['edit-workflow']=e=>{const w=features.workflows.find(w=>w.id===dataId(e));if(w.data.status==='running')throw Error('运行中的流程请先暂停，再修改步骤');return editWorkflow(w)};
act['pause-workflow']=async e=>{const w=await api('extras/workflow/'+dataId(e)+scope());await api('extras/workflow/'+w.id+scope(),{method:'PATCH',body:{revision:w.revision,data:{...w.data,status:w.data.status==='paused'?'idle':'paused',schedule_enabled:false}}});await render();toast(w.data.status==='paused'?'已恢复为手动待运行':'已暂停后续步骤，正在执行的模型调用可在 AI 运行记录中取消')};
act['run-workflow']=async e=>{const w=features.workflows.find(w=>w.id===dataId(e));if(w.data.status==='running')return act['workflow-results'](e);modal('运行工作流',`<div class="notice">${esc(w.data.title)} · ${w.data.nodes.length} 步<br>将消耗已配置模型的 API 额度，沿用你的单次与累计预算。结果保留为候选，不自动替换正文。</div>`,async()=>{toast('流程已启动，正在执行模型步骤');const request=api('workflows/'+w.id+'/run'+scope(),{method:'POST',body:{}});const poll=setInterval(()=>{if(state.page==='workflows')render()},2500);try{const result=await request;await render();toast(result.status==='completed'?'工作流已完成':'工作流停止：'+(result.error||result.status))}finally{clearInterval(poll)}})};
act['workflow-results']=async e=>{const w=await api('extras/workflow/'+dataId(e)+scope()),runs=await api('runs'+scope());modal(w.data.title+' · 运行结果',`<div class="notice">状态：${esc(w.data.status)} ${w.data.error?'· '+esc(w.data.error):''}</div>`+(w.data.results||[]).map(result=>{const r=runs.find(x=>x.id===result.run_id);return `<div class="candidate-card"><h3>${esc(tasks.find(t=>t[0]===result.action)?.[1]||result.action)}</h3><div class="candidate">${esc(r?.data.output||'结果在运行记录中')}</div>${r?btn('打开所属稿件','open-content',`data-id="${r.content_id}" type="button"`,'small'):''}</div>`}).join(''),null,true)};
act['open-usage']=async()=>{const data=await api('usage'+(state.accountId?scope():'')),rows=[...data.runs,...data.tests].sort((a,b)=>b.created_at.localeCompare(a.created_at)),totals={};for(const r of rows){const currency=r.data.currency||'USD';totals[currency]=(totals[currency]||0)+Number(r.data.estimated_cost||0)}modal('调用、Token 与估算费用',`<div class="notice">${acc()?esc(acc().name):'全局'} · 最近 1000 次任务 + 连接测试。价格来自你填写的单价；非供应商账单。没有返回 Token 用量时显示预算预留值，不当作实测费用。<br>${Object.entries(totals).map(([k,v])=>k+' '+v.toFixed(6)).join(' / ')||'暂无费用'}</div>${field('usage_search','筛选模型 / 任务 / Skill / 状态','')}<div class="table-wrap"><table><thead><tr><th>时间 / 任务</th><th>模型 / Skill</th><th>输入 / 输出 Token</th><th>估算费用</th><th>记录</th></tr></thead><tbody id="usage-rows">${rows.map(r=>`<tr data-usage="${esc(JSON.stringify(r.data)+' '+r.status)}"><td>${fmt(r.created_at)}<small>${esc(r.data.action||'连接测试')} / ${esc(r.status||'完成')}</small></td><td>${esc(r.data.model||r.provider_id||'—')}<small>${esc(r.data.skill_snapshot?.title||'未用 Skill')}</small></td><td>${r.data.usage_reported===false?'未知':r.data.usage?.input_tokens??'未知'} / ${r.data.usage_reported===false?'未知':r.data.usage?.output_tokens??'未知'}<small>${r.data.usage_reported===false?'供应商未回传用量':''}</small></td><td>${esc(r.data.currency||'USD')} ${Number(r.data.estimated_cost||0).toFixed(6)}</td><td>${r.status?btn('输入快照','run-snapshot',`data-id="${r.id}" type="button"`,'small'):''}</td></tr>`).join('')}</tbody></table></div>`,null,true);features.usageRuns=data.runs;$('#f-usage_search').oninput=e=>document.querySelectorAll('#usage-rows tr').forEach(row=>row.hidden=!row.dataset.usage.toLowerCase().includes(e.target.value.toLowerCase()))};
act['run-snapshot']=e=>{const r=features.usageRuns.find(r=>r.id===dataId(e));modal('不可变运行快照',`<div class="notice">${esc(r.id)}<br>${esc(r.data.routing_source||'指定模型')} · ${esc(r.data.prompt_hash||'')}</div><div class="candidate">${esc(JSON.stringify(r.data,null,2))}</div>`,null,true)};
act['multi-model']=async()=>{await flush();const [contents,providers]=await Promise.all([records('content'),records('provider')]);const available=providers.filter(p=>p.data.enabled&&p.data.protocol!=='image');if(available.length<2)throw Error('请先配置至少两个可用模型');if(!contents.length)throw Error('请先创建一篇稿件');modal('多模型候选与盲评',select('content_id','当前账号稿件',state.studio?.id||contents[0].id,contents.map(c=>[c.id,c.data.title]))+select('action','同一个任务','rewrite',tasks.filter(([k])=>['draft','rewrite','titles','review'].includes(k)))+available.map(p=>`<label class="radio-card"><input type="checkbox" name="provider_${p.id}"> ${esc(p.data.title)} / ${esc(p.data.model)}</label>`).join('')+field('instruction','所有模型使用相同补充要求','','textarea')+'<div class="notice">每次选 2–3 个模型，每个候选单独计费并保存调用快照。候选顺序随机，评分后可揭晓模型。</div>',async f=>{const selected=available.filter(p=>f['provider_'+p.id]==='on');if(selected.length<2||selected.length>3)throw Error('请选择 2–3 个模型');await flush();const c=contents.find(c=>c.id===f.content_id);toast('多个模型正在分别生成，结果会独立保存');const results=await Promise.allSettled(selected.map(p=>api('runs'+scope(),{method:'POST',body:{content_id:c.id,source_revision:c.revision,action:f.action,provider_id:p.id,instruction:f.instruction}})));features.multiRuns=results.map(r=>r.status==='fulfilled'?r.value:null).filter(r=>r?.status==='succeeded');features.multiErrors=results.map(r=>r.status==='rejected'?r.reason.message:r.value.status!=='succeeded'?r.value.data?.error:null).filter(Boolean);features.multiContent=c;features.multiProviders=available;features.multiRuns.sort(()=>Math.random()-.5);features.blindRevealed=false;showBlindReview()},true)};
function showBlindReview(){const runs=features.multiRuns;modal('多模型盲评 · '+features.multiContent.data.title,`<div class="notice">评分为你的主观判断，建议按事实准确、结构、表达、平台适配、风格一致性各 0–10 分。评分先保存，模型揭晓后再决定采用。${features.multiErrors.length?'<br>失败：'+features.multiErrors.map(esc).join('；'):''}</div>${runs.map((r,i)=>`<section class="blind-card"><h3>方案 ${String.fromCharCode(65+i)}${features.blindRevealed?' / '+esc(features.multiProviders.find(p=>p.id===r.data.provider_id)?.data.title||r.data.model):''}</h3><div class="candidate">${esc(r.data.output)}</div><div class="field-grid">${['事实准确','结构','表达','平台适配','风格一致'].map((name,k)=>field('score_'+i+'_'+k,name,'','number')).join('')}</div></section>`).join('')}`,async f=>{if(!runs.length)throw Error('没有成功候选');const ratings=runs.map((r,i)=>({run_id:r.id,scores:Array.from({length:5},(_,k)=>{const value=f['score_'+i+'_'+k];if(value===''||Number(value)<0||Number(value)>10)throw Error('每一项评分需为 0–10');return Number(value)})}));await api('extras/evaluation'+scope(),{method:'POST',body:{data:{title:features.multiContent.data.title+' / 多模型盲评',content_id:features.multiContent.id,run_ids:runs.map(r=>r.id),ratings,subjective:true}}});features.blindRevealed=true;modal('盲评已保存 · 揭晓模型',runs.map((r,i)=>`<section class="blind-card"><h3>方案 ${String.fromCharCode(65+i)} / ${esc(features.multiProviders.find(p=>p.id===r.data.provider_id)?.data.title||r.data.model)}</h3><p>五项评分：${ratings[i].scores.join(' / ')}（主观）</p><div class="candidate">${esc(r.data.output)}</div>${['titles','review'].includes(r.data.action)?'':btn('打开此候选并对比采纳','blind-candidate',`data-id="${r.id}" type="button"`,'primary small')}</section>`).join(''),null,true)},true)}
act['blind-candidate']=async e=>{const id=dataId(e);await go('studio',features.multiContent.id);state.compareRun=state.runs.find(r=>r.id===id)||features.multiRuns.find(r=>r.id===id);await act['compare-run']({dataset:{id}})};
act['evaluation-detail']=e=>{const r=features.evaluations.find(x=>x.id===dataId(e));modal(r.data.title,`<div class="notice">人工主观评分，非预测表现。</div><div class="candidate">${esc(JSON.stringify(r.data,null,2))}</div>`,null,true)};
const finalBind=bindPage;bindPage=function(){finalBind();if($('#f-layout-content'))$('#f-layout-content').onchange=async e=>{await flush();state.layoutId=e.target.value;await render()};if($('#ai-feedback')&&!$('#allow-fallback')){$('#ai-feedback').insertAdjacentHTML('beforebegin','<label class="caption"><input id="allow-fallback" type="checkbox"> 本次允许使用已授权的备用模型</label><details style="margin:10px 0"><summary>本次高级参数</summary><div class="field"><label for="run-temperature">temperature（模型支持才填写）</label><input id="run-temperature" type="number" min="0" max="2" step="0.1" placeholder="留空使用供应商默认"></div><div class="field"><label for="run-max-tokens">本次输出 Token（可覆盖模型默认）</label><input id="run-max-tokens" type="number" min="0" placeholder="留空或 0 使用模型默认"></div></details>')}};
originalAPI('local/auth-status').then(status=>{if(status.locked)showUnlock()}).catch(()=>{});
act['generate-image']=async()=>{const providers=(await records('provider')).filter(p=>p.data.protocol==='image'&&p.data.enabled);if(!providers.length)throw Error('请先在模型配置中添加「图像生成 / Images API」配置、Key 和每张估算价格');modal('生成真实图片',select('provider_id','图像模型',providers[0].id,providers.map(p=>[p.id,p.data.title+' / '+p.data.currency+' '+p.data.image_price+' 每张（估算）']))+field('title','素材名称','AI 配图')+field('prompt','图片描述','','textarea')+select('size','请求尺寸','1024x1024',[['1024x1024','1024 × 1024'],['1024x1536','1024 × 1536'],['1536x1024','1536 × 1024']])+select('quality','质量（GPT Image）','auto',[['auto','自动'],['low','低'],['medium','中'],['high','高']])+'<div class="notice">会调用你配置的图像服务并产生费用。成功后写入当前账号素材库，保留提示词、模型、图片哈希和估算费用。失败不会显示为生成成功。</div>',async f=>{toast('图像模型正在生成，请稍候…');await api('generate-image'+scope(),{method:'POST',body:f});await act.assets();toast('生成图片已存入当前账号素材库')},true)};
act['test-provider']=async e=>{e.disabled=true;e.textContent='测试中…';try{const r=await api('providers/'+dataId(e)+'/test'+(state.accountId?scope():''),{method:'POST',body:{}});toast('连接成功 · '+r.latency_ms+' ms · '+(r.usage.input_tokens+r.usage.output_tokens)+' tokens；已记入费用账本')}finally{e.disabled=false;e.textContent='连接测试'}};
act['cancel-run']=async e=>{await flush();await api('runs/'+dataId(e)+'/cancel'+scope(),{method:'POST',body:{}});state.runs=await api('runs'+scope());if($('#candidates'))$('#candidates').innerHTML=state.runs.filter(r=>r.content_id===state.studio?.id).slice(0,5).map(runCard).join('');toast('已请求取消上游调用，部分输出保留；已产生的供应商费用仍可能计费')};
act['asset-trash']=async()=>{const rows=await api('records/asset'+scope()+'&deleted=1');modal('已移入回收状态的素材',rows.map(r=>`<div class="list-row"><div class="list-main"><h4>${esc(r.data.title)}</h4><p>历史引用仍保留；可恢复到素材库。</p></div>${btn('恢复素材','restore-asset',`data-id="${r.id}" data-revision="${r.revision}" type="button"`,'small')}</div>`).join('')||empty('没有已删除素材',''),null,true)};
act['restore-asset']=async e=>{await api('records/asset/'+dataId(e)+scope(),{method:'PATCH',body:{revision:Number(e.dataset.revision),restore_deleted:true,data:{}}});await act.assets();toast('素材已恢复')};
const beforeAssetTrash=act.assets;act.assets=async()=>{await beforeAssetTrash();$('#modal .notice').insertAdjacentHTML('afterend',btn('查看回收素材','asset-trash','type="button" style="margin-bottom:14px"','small'))};
act['experiments']=async()=>{const experiments=await extraList('experiment');features.experiments=experiments;modal('真实实验记录',`<div class="notice">只比较你实际发布、实际采集的作品。不同作品通常存在受众、时间与分发差异；不会把自然流量差异当成随机 A/B 实验或显著结论。</div>${btn('创建实验记录','add-experiment','type="button"','primary small')}`+experiments.map(e=>`<div class="list-row"><div class="list-main"><h4>${esc(e.data.title)}</h4><p>${esc(e.data.hypothesis||'')} · ${e.data.job_ids.length} 篇作品</p></div>${btn('查看指标比较','experiment-detail',`data-id="${e.id}" type="button"`,'small')}</div>`).join(''),null,true)};
act['add-experiment']=async()=>{const jobs=(await records('job')).filter(j=>j.data.status==='published');if(jobs.length<2)throw Error('至少需要两篇已确认真实发布的作品');modal('创建观察实验',field('title','实验名称','')+field('hypothesis','准备验证的假设','','textarea')+select('baseline','基准作品',jobs[0].id,jobs.map(j=>[j.id,j.data.title]))+select('variant','比较作品',jobs[1].id,jobs.map(j=>[j.id,j.data.title]))+field('conditions','发布时间、受众、周期和分母的可比条件','','textarea'),async f=>{if(f.baseline===f.variant)throw Error('请选择两篇不同作品');await api('extras/experiment'+scope(),{method:'POST',body:{data:{title:f.title,hypothesis:f.hypothesis,conditions:f.conditions,job_ids:[f.baseline,f.variant],method:'observational',status:'recorded'}}});await act.experiments()})};
act['experiment-detail']=async e=>{const experiment=await api('extras/experiment/'+dataId(e)+scope()),allMetrics=await records('metric'),allJobs=await records('job'),latest=new Map(latestMetrics(allMetrics).map(m=>[m.data.job_id,m]));modal('真实指标对照 · '+experiment.data.title,`<div class="notice">假设：${esc(experiment.data.hypothesis||'未填写')}<br>可比条件：${esc(experiment.data.conditions||'未确认')}<br>以下为各作品最新累计快照，观察时长可能不同，不能据此推断因果或显著胜负。</div><div class="table-wrap"><table><thead><tr><th>作品 / 采集时间</th><th>阅读</th><th>点赞率（点赞/阅读）</th><th>互动率（四类互动/阅读）</th></tr></thead><tbody>${experiment.data.job_ids.map(id=>{const m=latest.get(id)?.data,j=allJobs.find(j=>j.id===id),valid=m?.reads>0,known=m&&['likes','saves','comments','shares'].every(k=>m[k]!==null&&m[k]!==undefined);return `<tr><td>${esc(j?.data.title||id)}<small>${m?fmt(m.observed_at):'尚无真实指标'}</small></td><td>${m?.reads??'—'}</td><td>${valid&&m.likes!==null?(m.likes/m.reads*100).toFixed(2)+'%':'—'}</td><td>${valid&&known?(['likes','saves','comments','shares'].reduce((sum,k)=>sum+m[k],0)/m.reads*100).toFixed(2)+'%':'—'}</td></tr>`}).join('')}</tbody></table></div>`,null,true)};
const withExperimentsAnalytics=pages.analytics;pages.analytics=async()=>await withExperimentsAnalytics()+`<section class="panel"><div class="panel-head"><h2>真实实验与指标对照</h2></div><p class="subtitle">保存假设与可比条件，对照已发布作品的最新真实快照。缺失指标保持未知。</p>${btn('管理实验记录','experiments','','small')}</section>`;
let lastActivitySignal=0;
function signalLocalActivity(){if(Date.now()-lastActivitySignal<15000||$('#unlock-form'))return;lastActivitySignal=Date.now();api('local/activity',{method:'POST',body:{}}).catch(()=>{})}
document.addEventListener('pointerdown',signalLocalActivity,{passive:true});document.addEventListener('keydown',signalLocalActivity,{passive:true});
setInterval(()=>originalAPI('local/auth-status').then(status=>{if(status.locked)showUnlock()}).catch(()=>{}),15000);
window.addEventListener('beforeunload',e=>{if(features.cardDirty||features.cardSaving){e.preventDefault();e.returnValue='排版尚未保存'}});
